"import fs from 'fs';

const raw = fs.readFileSync('Clone-srefalsteam/data/product.json', 'utf8');
const p = JSON.parse(raw).product;

console.log('=== PRODUCT SUMMARY ===');
console.log('Title:', p.title);
console.log('Handle:', p.handle);
console.log('Vendor:', p.vendor);
console.log('Product Type:', p.product_type);
console.log('Tags:', p.tags);
console.log('Variants:');
p.variants.forEach(v => {
  console.log(`  - ID: ${v.id} | Title: ${v.title} | Price: ${v.price} | CompareAt: ${v.compare_at_price} | SKU: ${v.sku}`);
});

console.log(`Total Images: ${p.images.length}`);
p.images.forEach((img, i) => {
  console.log(`  [${i+1}] ${img.src}`);
});

console.log('Body HTML length:', p.body_html ? p.body_html.length : 0);
if (p.body_html) {
  console.log('Body HTML snippet:\n', p.body_html.slice(0, 500));
}
"

"import fs from 'fs';

const html = fs.readFileSync('Clone-srefalsteam/data/product.html', 'utf8');

console.log('HTML size:', html.length);

// Check theme name or shopify object
const themeMatch = html.match(/theme\s*=\s*({[^}]+})/i) || html.match(/"theme":\s*({[^}]+})/i);
if (themeMatch) console.log('Theme info:', themeMatch[1]);

// Check section IDs
const sectionRegex = /id="shopify-section-([^"]+)"/g;
let match;
const sections = [];
while ((match = sectionRegex.exec(html)) !== null) {
  sections.push(match[1]);
}
console.log('Found sections:', sections.length);
sections.forEach((s, idx) => console.log(`  [${idx+1}] ${s}`));

// Check stylesheet links
const cssRegex = /<link[^>]+rel=["']stylesheet["'][^>]*>/gi;
const cssLinks = html.match(cssRegex) || [];
console.log('\nStylesheet links count:', cssLinks.length);
cssLinks.forEach(l => console.log('  ', l));

// Check template name
const templateMatch = html.match(/"template":\s*"([^"]+)"/) || html.match(/template-([a-zA-Z0-9_-]+)/);
console.log('\nTemplate match:', templateMatch ? templateMatch[0] : 'None');

// Check price, add to cart, bundles, etc.
const hasAtc = html.includes('name="add"') || html.includes('add-to-cart') || html.includes('AddToCart');
console.log('Has ATC button:', hasAtc);

// Search for unique headings or sales copy in HTML
const h1Match = html.match(/<h1[^>]*>([\s\S]*?)<\/h1>/gi);
console.log('\nH1 tags:', h1Match);
"

"import fs from 'fs';

const html = fs.readFileSync('Clone-srefalsteam/data/product.html', 'utf8');

// Find where main section starts and ends, or inspect each section
const sectionRegex = /<div id="shopify-section-([^"]+)" class="shopify-section([^"]*)">([\s\S]*?)(?=<div id="shopify-section-|<\/main>|<footer|$)/g;

let match;
let count = 0;
while ((match = sectionRegex.exec(html)) !== null) {
  count++;
  const sectionId = match[1];
  const sectionClass = match[2];
  const content = match[3];
  console.log(`\n=== Section [${count}] ${sectionId} ===`);
  console.log(`Classes: ${sectionClass}`);
  console.log(`Length: ${content.length}`);
  // Extract headings or snippet
  const headings = content.match(/<h[1-6][^>]*>([\s\S]*?)<\/h[1-6]>/gi) || [];
  console.log('Headings:', headings.map(h => h.replace(/<[^>]+>/g, '').trim()));
}
"

"import fs from 'fs';

const html = fs.readFileSync('Clone-srefalsteam/data/product.html', 'utf8');

const mainMatch = html.match(/<main[^>]*>([\s\S]*?)<\/main>/i);
if (mainMatch) {
  console.log('Main content length:', mainMatch[1].length);
  const mainHtml = mainMatch[1];

  // Find all shopify-section divs inside main
  const re = /<div id="shopify-section-([^"]+)"/g;
  let m;
  while ((m = re.exec(mainHtml)) !== null) {
    console.log('Main Section ID:', m[1]);
  }
} else {
  console.log('No <main> tag found!');
}
"

"import fs from 'fs';

const html = fs.readFileSync('Clone-srefalsteam/data/product.html', 'utf8');

console.log('--- REVIEWS CHECK ---');
['judge.me', 'loox', 'yotpo', 'spr-badge', 'review', 'rating'].forEach(k => {
  const count = (html.match(new RegExp(k, 'gi')) || []).length;
  console.log(`${k}: ${count} occurrences`);
});

// Look for review count and average rating
const ratingSnippet = html.match(/class="[^"]*rating[^"]*"[\s\S]{0,300}/gi);
if (ratingSnippet) {
  console.log('\nRating snippets:');
  ratingSnippet.slice(0, 3).forEach(s => console.log(s.slice(0, 150)));
}

// Look for bundle quantity options (e.g. 1 unit, 2 units, etc.)
const bundleMatches = html.match(/bundle|pack|quantity|save \d+%/gi);
console.log('\nBundle keyword occurrences:', bundleMatches ? bundleMatches.length : 0);

// Look for form tag
const formMatch = html.match(/<form[^>]+action=["'][^"']*\/cart\/add["'][^>]*>([\s\S]*?)<\/form>/i);
if (formMatch) {
  console.log('\nFound Cart Form! Length:', formMatch[0].length);
  // look for inputs
  const inputs = formMatch[0].match(/<input[^>]+>/gi) || [];
  console.log('Form inputs:', inputs);
} else {
  console.log('\nCart form with action="/cart/add" not found directly, checking for any form');
  const allForms = html.match(/<form[^>]*>([\s\S]*?)<\/form>/gi) || [];
  console.log('Total forms:', allForms.length);
  allForms.forEach((f, idx) => console.log(`Form [${idx+1}]:`, f.slice(0, 200)));
}
"

