"  // Observer to reveal sticky Add to Cart bar once the main purchase button scrolls out of view
  function initStickyBar() {
    const mainAtc = document.getElementById('willaPdpAtcBtn');
    const stickyBar = document.getElementById('willaStickyAtc');
    if (mainAtc && stickyBar) {
      const observer = new IntersectionObserver((entries) => {
        entries.forEach(entry => {
          if (entry.isIntersecting) {
            stickyBar.classList.remove('visible');
          } else if (entry.boundingClientRect.top < 0) {
            stickyBar.classList.add('visible');
          } else {
            stickyBar.classList.remove('visible');
          }
        });
      }, { threshold: 0.1 });
      observer.observe(mainAtc);
    }
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', initStickyBar);
  } else {
    initStickyBar();
  }"

