"import fs from 'fs';

const CLIENT_ID = '172e9e29abd0fe12f671d8441479c7c2';
const CLIENT_SECRET = 'shpss_REDACTED_SECRET';
const SHOP = 'dsdujr-vn.myshopify.com';

async function getAccessToken() {
  const res = await fetch(`https://${SHOP}/admin/oauth/access_token`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      client_id: CLIENT_ID,
      client_secret: CLIENT_SECRET,
      grant_type: 'client_credentials'
    })
  });
  const data = await res.json();
  return data.access_token;
}

async function run() {
  const token = await getAccessToken();
  const query = `
    query {
      files(first: 50, sortKey: CREATED_AT, reverse: true) {
        edges {
          node {
            ... on MediaImage {
              id
              createdAt
              image {
                url
                altText
                originalSrc
              }
            }
          }
        }
      }
    }
  `;
  const res = await fetch(`https://${SHOP}/admin/api/2024-10/graphql.json`, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'X-Shopify-Access-Token': token
    },
    body: JSON.stringify({ query })
  });
  const data = await res.json();
  console.log('Total files found:', data.data.files.edges.length);
  for (const edge of data.data.files.edges) {
    const img = edge.node.image;
    if (img) {
      console.log(`- Created: ${edge.node.createdAt} | URL: ${img.url}`);
    }
  }
}

run().catch(console.error);
"

"import fs from 'fs';

async function run() {
  const urls = [
    'https://cdn.shopify.com/s/files/1/0826/2483/9865/files/tgwkEV9Zr.jpg?v=1792905883',
    'https://cdn.shopify.com/s/files/1/0826/2483/9865/files/3PKEj9qFE9.jpg?v=1792905880'
  ];
  for (const url of urls) {
    const filename = url.split('/').pop().split('?')[0];
    const res = await fetch(url);
    const buf = Buffer.from(await res.arrayBuffer());
    fs.writeFileSync(`scratch_colors/${filename}`, buf);
    console.log(`Saved ${filename} (${buf.length} bytes)`);
  }
}
run();
"

