import fs from 'fs';
async function inspectTab() {
  const tabsRes = await fetch('http://localhost:9222/json');
  const tabs = await tabsRes.json();
  const tab = tabs.find(t => t.id === 'F30B7C1DA4E05A408A1972D3BF949DB3') || tabs.find(t => t.url && t.url.includes('saker'));
  console.log('Connecting to tab:', tab.id, tab.url);

  const ws = new WebSocket(tab.webSocketDebuggerUrl);
  let id = 1;
  function send(method, params = {}) {
    return new Promise((resolve, reject) => {
      const curId = id++;
      const handler = (evt) => {
        const msg = JSON.parse(evt.data.toString());
        if (msg.id === curId) {
          ws.removeEventListener('message', handler);
          if (msg.error) reject(msg.error);
          else resolve(msg.result);
        }
      };
      ws.addEventListener('message', handler);
      ws.send(JSON.stringify({ id: curId, method, params }));
    });
  }

  ws.addEventListener('open', async () => {
    await new Promise(r => setTimeout(r, 4000));
    const titleRes = await send('Runtime.evaluate', { expression: 'document.title' });
    const urlRes = await send('Runtime.evaluate', { expression: 'window.location.href' });
    const htmlRes = await send('Runtime.evaluate', { expression: 'document.documentElement.outerHTML' });
    console.log('Page Title:', titleRes.result.value);
    console.log('Current URL:', urlRes.result.value);
    console.log('HTML Length:', htmlRes.result.value.length);
    fs.writeFileSync('saker_leaf_blower_live.html', htmlRes.result.value);
    console.log('Saved live HTML to saker_leaf_blower_live.html');
    ws.close();
  });
}
inspectTab().catch(console.error);
