"import fs from 'fs';

function parseCheckoutHtml() {
  const html = fs.readFileSync('cheese_grater_checkout.html', 'utf8');
  console.log('HTML size:', html.length);

  // Search for options
  const re = /(White|Green)[^"']*(1\s*pc|2\s*pcs)/gi;
  const matches = [...html.matchAll(re)].map(m => m[0]);
  console.log('Option matches:', matches);

  // Search for prices
  const priceMatches = [...html.matchAll(/(\d+\.\d{2})/g)].map(m => m[0]);
  const uniquePrices = [...new Set(priceMatches)].filter(p => Number(p) > 20 && Number(p) < 300);
  console.log('Unique prices:', uniquePrices);

  // Extract all image URLs from myshopage
  const imgMatches = [...html.matchAll(/https:\/\/cdn\.myshopage\.com\/[a-f0-9-]+\.(jpg|png|webp|gif)/gi)].map(m => m[0]);
  console.log('Unique image URLs:', [...new Set(imgMatches)]);
}

parseCheckoutHtml();
"

"import fs from 'fs';

function parseLanding() {
  const html = fs.readFileSync('cheese_grater_raw.html', 'utf8');
  console.log('Landing HTML size:', html.length);

  // Find all images and GIFs
  const imgUrls = [...html.matchAll(/https:\/\/cdn\.myshopage\.com\/[a-f0-9-/_]+(\.jpg|\.png|\.gif|\.webp)?/gi)].map(m => m[0]);
  const uniqueUrls = [...new Set(imgUrls)];
  console.log('Total unique myshopage images in landing:', uniqueUrls.length);

  const gifs = uniqueUrls.filter(u => u.includes('gif') || u.includes('.gif'));
  console.log('GIFs found:', gifs);

  // Extract headings
  const hMatches = [...html.matchAll(/<(h[1-4]|div)[^>]*class="[^"]*(title|heading)[^"]*"[^>]*>(.*?)<\/\1>/gis)]
    .map(m => m[3].replace(/<[^>]+>/g, '').trim())
    .filter(t => t.length > 5 && t.length < 150);
  console.log('Headings found in landing:', [...new Set(hMatches)].slice(0, 20));

  // Write all unique image URLs to a file
  fs.writeFileSync('cheese_grater_image_urls.json', JSON.stringify(uniqueUrls, null, 2), 'utf8');
}

parseLanding();
"

"import fs from 'fs';

async function testImages() {
  const urls = JSON.parse(fs.readFileSync('cheese_grater_image_urls.json', 'utf8'));
