  const results = [];
  for (let i = 0; i < urls.length; i++) {
    const u = urls[i];
    try {
      const res = await fetch(u, {
        headers: { 'Referer': 'https://m.sakerplus.com/', 'User-Agent': 'Mozilla/5.0' }
      });
      const contentType = res.headers.get('content-type');
