"import fs from 'fs';

const CLIENT_ID = '172e9e29abd0fe12f671d8441479c7c2';
const CLIENT_SECRET = 'shpss_REDACTED_SECRET';
const SHOP_DOMAIN = 'dsdujr-vn.myshopify.com';
const THEME_ID = '186607567033';

async function getAccessToken() {
  const tokenRes = await fetch(`https://${SHOP_DOMAIN}/admin/oauth/access_token`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ client_id: CLIENT_ID, client_secret: CLIENT_SECRET, grant_type: 'client_credentials' })
  });
  const data = await tokenRes.json();
  return data.access_token;
}

async function getSection() {
  const token = await getAccessToken();
  const res = await fetch(`https://${SHOP_DOMAIN}/admin/api/2024-10/themes/${THEME_ID}/assets.json?asset[key]=sections/willa-main-product.liquid`, {
    headers: { 'X-Shopify-Access-Token': token }
  });
  const data = await res.json();
  fs.writeFileSync('live_willa-main-product.liquid', data.asset.value);
  console.log('Downloaded live_willa-main-product.liquid (' + data.asset.value.length + ' bytes)');
}

getSection().catch(console.error);
"

"import fs from 'fs';

async function checkProductTemplate() {
  const tabsRes = await fetch('http://localhost:9222/json');
  const tabs = await tabsRes.json();
  const pageTab = tabs.find(t => t.type === 'page' && t.webSocketDebuggerUrl);

  const ws = new WebSocket(pageTab.webSocketDebuggerUrl);
  let idCounter = 1;
  function send(method, params = {}) {
    return new Promise((resolve, reject) => {
      const id = idCounter++;
      const handler = evt => {
        const msg = JSON.parse(evt.data.toString());
        if (msg.id === id) {
          ws.removeEventListener('message', handler);
          if (msg.error) reject(msg.error);
          else resolve(msg.result);
        }
      };
      ws.addEventListener('message', handler);
      ws.send(JSON.stringify({ id, method, params }));
    });
  }

  await new Promise(r => ws.addEventListener('open', r));

  const result = await send('Runtime.evaluate', {
    expression: `
      (() => {
        const bundleWrap = document.querySelector('[class*="bundle"], [class*="variant"]');
        const sections = Array.from(document.querySelectorAll('main section, [class*="shopify-section"]')).map(s => ({
          id: s.id,
          className: s.className,
          html: s.innerHTML.slice(0, 300)
        }));
        const bundleHtml = document.querySelector('.bundle-container, .willa-pdp-bundle-wrap, .product__info-container, .product-form')?.outerHTML?.slice(0, 1500);

        return {
          sections,
          bundleHtml
        };
      })()
    `,
    returnByValue: true
  });

  fs.writeFileSync('pdp_rendered_dom.json', JSON.stringify(result.result.value, null, 2));
  console.log('Saved pdp_rendered_dom.json');
  ws.close();
}

checkProductTemplate().catch(console.error);
"

