"import fs from 'fs';

function extractImgsFromHtml(html, pageName) {
  const matches = [...html.matchAll(/<img[^>]+src=["']([^"']+)["'][^>]*>/gi)];
  return matches.map(m => {
    const fullTag = m[0];
    const src = m[1];
    const altMatch = fullTag.match(/alt=["']([^"']*)["']/i);
    return {
      page: pageName,
      src,
      alt: altMatch ? altMatch[1] : ''
    };
  });
}

