    },
    body: JSON.stringify({
      asset: {
        key: `assets/${filename}`,
        attachment: base64
      }
    })
  });
  const data = await res.json();
  if (data.errors) throw new Error(`Asset upload error: ${JSON.stringify(data.errors)}`);
  return data.asset.public_url;
}

