"import fs from 'fs';

const CLIENT_ID = '172e9e29abd0fe12f671d8441479c7c2';
const CLIENT_SECRET = 'shpss_REDACTED_SECRET';
const SHOP = 'dsdujr-vn.myshopify.com';
const DRAFT_THEME_ID = '187597717689';

async function getAccessToken() {
  const tRes = await fetch(`https://${SHOP}/admin/oauth/access_token`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ client_id: CLIENT_ID, client_secret: CLIENT_SECRET, grant_type: 'client_credentials' })
  });
  const data = await tRes.json();
  return data.access_token;
}

async function fetchAsset(token, key) {
  const res = await fetch(`https://${SHOP}/admin/api/2024-10/themes/${DRAFT_THEME_ID}/assets.json?asset[key]=${key}`, {
    headers: { 'X-Shopify-Access-Token': token }
  });
  const d = await res.json();
  return d.asset ? d.asset.value : null;
}

async function main() {
  const token = await getAccessToken();
  const willaCart = await fetchAsset(token, 'sections/willa-cart-drawer.liquid');
  fs.writeFileSync('scripts/audit_willa_cart_drawer.liquid', willaCart || '');
  console.log('Saved sections/willa-cart-drawer.liquid, length:', (willaCart || '').length);

  const trustpilotStars = await fetchAsset(token, 'snippets/trustpilot-stars.liquid');
  console.log('Trustpilot snippet length:', (trustpilotStars || '').length);

  const sakerReviews = await fetchAsset(token, 'sections/saker-reviews-widget.liquid');
  console.log('saker-reviews-widget length:', (sakerReviews || '').length);
}

main().catch(console.error);
"

